insert into public.programs (id, code, title, trainer_id, data)
values ('virtual-assistant', 'VA-510', 'Virtual Assistant NC II', 'tr-005', $prog${"id":"virtual-assistant","code":"VA-510","title":"Virtual Assistant NC II","category":"Information Technology","level":"NC II","special":false,"enrollable":false,"description":"Become a professional virtual assistant: admin support, communication, social media management and tool proficiency.","overview":"The Virtual Assistant NC II program prepares trainees for remote work as a VA. It covers the VA profession, remote work setup, administrative support, client communication, customer support, social media management, and tool proficiency — including a proctored typing test evaluation.","duration":"8 Weeks","hours":100,"fee":5000,"color":"from-indigo-500 to-violet-600","image":"/courses/virtual-assistant.jpg","coverBackground":false,"requirements":["At least 18 years old","High School graduate or ALS equivalent","Own laptop/computer with webcam","Stable internet connection (min. 5 Mbps)","Birth certificate (PSA)","2 pcs. 2x2 ID picture"],"trainerId":"tr-005","competencies":[{"id":"virtual-assistant-basic","type":"Basic","title":"Basic Competency","description":"Foundational skills required of every trainee: communication, numeracy, digital literacy and workplace behavior.","lessons":[{"videoUrl":"","published":true,"order":1,"id":"virtual-assistant-basic-l1","title":"Reading, Writing & Comprehension","description":"Develop the ability to read, interpret and write workplace documents, forms and simple reports.","duration":45,"video":"Introduction to Workplace Literacy","materials":[{"id":"virtual-assistant-basic-l1-m1","name":"Reading Comprehension Guide.pdf","type":"pdf","url":""},{"id":"virtual-assistant-basic-l1-m2","name":"Workplace Forms Template.docx","type":"doc","url":""}],"content":"This lesson builds the foundational literacy skills needed in a technical-vocational workplace. You will practice reading instructions, interpreting forms, and writing simple reports and messages clearly and accurately.","quizId":"virtual-assistant-basic-l1-quiz"},{"videoUrl":"","published":true,"order":2,"id":"virtual-assistant-basic-l2","title":"Basic Communication Skills","description":"Learn verbal and non-verbal communication techniques for professional workplace interaction.","duration":40,"video":"Effective Workplace Communication","materials":[{"id":"virtual-assistant-basic-l2-m1","name":"Communication Etiquette Handout.pdf","type":"pdf","url":""}],"content":"Communication is the backbone of any workplace. This lesson covers active listening, professional tone, giving and receiving feedback, and adapting your communication style to different audiences.","quizId":"virtual-assistant-basic-l2-quiz"},{"videoUrl":"","published":true,"order":3,"id":"virtual-assistant-basic-l3","title":"Basic Digital Literacy","description":"Familiarize yourself with computers, the internet, email and basic productivity tools.","duration":60,"video":"Getting Started with Computers","materials":[{"id":"virtual-assistant-basic-l3-m1","name":"Digital Skills Workbook.pdf","type":"pdf","url":""},{"id":"virtual-assistant-basic-l3-m2","name":"Keyboard Shortcuts Cheatsheet.pdf","type":"pdf","url":""}],"content":"Digital literacy is essential for modern employment. This lesson introduces operating systems, file management, internet browsing, email, and cloud-based productivity tools.","quizId":"virtual-assistant-basic-l3-quiz"},{"videoUrl":"","published":true,"order":4,"id":"virtual-assistant-basic-l4","title":"Workplace Behavior & Professionalism","description":"Understand workplace ethics, punctuality, grooming, and professional conduct.","duration":35,"video":"Professional Conduct at Work","materials":[{"id":"virtual-assistant-basic-l4-m1","name":"Code of Conduct.pdf","type":"pdf","url":""}],"content":"Professionalism covers punctuality, appropriate attire, respect for colleagues, following rules and regulations, and taking responsibility for your work.","quizId":"virtual-assistant-basic-l4-quiz"}]},{"id":"virtual-assistant-common","type":"Common","title":"Common Competency","description":"Skills common across technical-vocational industries: workplace communication, safety, customer service and teamwork.","lessons":[{"videoUrl":"","published":true,"order":1,"id":"virtual-assistant-common-l1","title":"Workplace Communication","description":"Communicate effectively with clients, colleagues and supervisors using industry-appropriate language.","duration":50,"video":"Communicating in the Workplace","materials":[{"id":"virtual-assistant-common-l1-m1","name":"Communication Scenarios.pdf","type":"pdf","url":""}],"content":"This lesson focuses on industry-specific communication: handling inquiries, reporting incidents, participating in meetings, and documenting work activities.","quizId":"virtual-assistant-common-l1-quiz"},{"videoUrl":"","published":true,"order":2,"id":"virtual-assistant-common-l2","title":"Workplace Safety & Emergency Procedures","description":"Identify hazards, follow OSH standards, and respond to workplace emergencies.","duration":55,"video":"Occupational Safety and Health","materials":[{"id":"virtual-assistant-common-l2-m1","name":"OSH Standards Manual.pdf","type":"pdf","url":""},{"id":"virtual-assistant-common-l2-m2","name":"Emergency Evacuation Plan.pdf","type":"pdf","url":""}],"content":"Occupational Safety and Health (OSH) is a legal requirement. Learn to identify hazards, use protective equipment, follow safety signage, and respond to emergencies such as fire, earthquake, and medical incidents.","quizId":"virtual-assistant-common-l2-quiz"},{"videoUrl":"","published":true,"order":3,"id":"virtual-assistant-common-l3","title":"Customer Service Excellence","description":"Deliver quality service that meets and exceeds customer expectations.","duration":45,"video":"Service Quality Standards","materials":[{"id":"virtual-assistant-common-l3-m1","name":"Customer Service Standards.pdf","type":"pdf","url":""}],"content":"Excellent customer service builds loyalty and reputation. Learn the principles of service quality, handling complaints, and creating positive customer experiences.","quizId":"virtual-assistant-common-l3-quiz"},{"videoUrl":"","published":true,"order":4,"id":"virtual-assistant-common-l4","title":"Working with Others & Time Management","description":"Collaborate effectively in teams and manage your time and priorities.","duration":40,"video":"Teamwork and Productivity","materials":[{"id":"virtual-assistant-common-l4-m1","name":"Teamwork Activity Sheet.pdf","type":"pdf","url":""}],"content":"Success in the workplace depends on teamwork and personal productivity. This lesson covers collaboration, conflict resolution, prioritization, and effective scheduling.","quizId":"virtual-assistant-common-l4-quiz"}]},{"id":"virtual-assistant-core","type":"Core","title":"Core Competency","description":"Core competencies of the Virtual Assistant program: VA fundamentals, administrative support, communication and customer support, and social media & tool proficiency.","lessons":[],"units":[{"id":"virtual-assistant-core-u1","title":"Introduction to Virtual Assistance","description":"Understand the VA industry, roles and remote work fundamentals.","lessons":[{"videoUrl":"","published":true,"order":1,"id":"virtual-assistant-core-u1-l1","title":"The Virtual Assistant Profession","description":"Understand what a VA does, niches, and client relationships.","duration":45,"video":"The Virtual Assistant Profession","materials":[{"id":"virtual-assistant-core-u1-l1-m1","name":"VA Career Guide.pdf","type":"pdf","url":""}],"content":"Learn about the different VA niches (admin, social media, e-commerce, real estate), rates, and building client relationships.","quizId":"virtual-assistant-core-u1-l1-quiz"},{"videoUrl":"","published":true,"order":2,"id":"virtual-assistant-core-u1-l2","title":"Remote Work Setup & Productivity","description":"Set up a home office and manage remote productivity.","duration":40,"video":"Remote Work Setup & Productivity","materials":[{"id":"virtual-assistant-core-u1-l2-m1","name":"Remote Setup Checklist.pdf","type":"pdf","url":""}],"content":"Configure your workstation, internet, backup power, and time-zone management for reliable remote work.","quizId":"virtual-assistant-core-u1-l2-quiz"}]},{"id":"virtual-assistant-core-u2","title":"Administrative Support","description":"Provide email, calendar and document management support.","lessons":[{"videoUrl":"","published":true,"order":1,"id":"virtual-assistant-core-u2-l1","title":"Email & Calendar Management","description":"Manage inboxes, filters and shared calendars.","duration":50,"video":"Email & Calendar Management","materials":[{"id":"virtual-assistant-core-u2-l1-m1","name":"Email Management Guide.pdf","type":"pdf","url":""}],"content":"Learn inbox zero techniques, labeling, canned responses, scheduling, and calendar coordination.","quizId":"virtual-assistant-core-u2-l1-quiz"},{"videoUrl":"","published":true,"order":2,"id":"virtual-assistant-core-u2-l2","title":"Document & Data Management","description":"Create documents, spreadsheets and manage cloud files.","duration":50,"video":"Document & Data Management","materials":[{"id":"virtual-assistant-core-u2-l2-m1","name":"Document Templates.zip","type":"zip","url":""}],"content":"Work with Google Workspace and Microsoft 365 to create documents, spreadsheets, and organized cloud folders.","quizId":"virtual-assistant-core-u2-l2-quiz"}]},{"id":"virtual-assistant-core-u3","title":"Communication & Customer Support","description":"Handle client communication and customer support tasks.","lessons":[{"videoUrl":"","published":true,"order":1,"id":"virtual-assistant-core-u3-l1","title":"Professional Client Communication","description":"Communicate professionally via email, chat and video.","duration":45,"video":"Professional Client Communication","materials":[{"id":"virtual-assistant-core-u3-l1-m1","name":"Client Email Templates.pdf","type":"pdf","url":""}],"content":"Draft professional emails, run meetings, and manage client communication tools like Slack and Zoom.","quizId":"virtual-assistant-core-u3-l1-quiz"},{"videoUrl":"","published":true,"order":2,"id":"virtual-assistant-core-u3-l2","title":"Customer Support Basics","description":"Provide helpdesk and customer support using ticketing tools.","duration":50,"video":"Customer Support Basics","materials":[{"id":"virtual-assistant-core-u3-l2-m1","name":"Support Playbook.pdf","type":"pdf","url":""}],"content":"Learn ticketing systems, response templates, escalation, and measuring customer satisfaction.","quizId":"virtual-assistant-core-u3-l2-quiz"}]},{"id":"virtual-assistant-core-u4","title":"Social Media & Tool Proficiency","description":"Manage social media and master common VA tools.","lessons":[{"videoUrl":"","published":true,"order":1,"id":"virtual-assistant-core-u4-l1","title":"Social Media Management","description":"Schedule and manage content across social platforms.","duration":50,"video":"Social Media Management","materials":[{"id":"virtual-assistant-core-u4-l1-m1","name":"Content Calendar.xlsx","type":"xls","url":""}],"content":"Use scheduling tools, content calendars and analytics to manage social media accounts.","quizId":"virtual-assistant-core-u4-l1-quiz"},{"videoUrl":"","published":true,"order":2,"id":"virtual-assistant-core-u4-l2","title":"Typing Proficiency & Data Entry","description":"Develop fast and accurate typing for data entry tasks.","duration":40,"video":"Typing Proficiency & Data Entry","materials":[{"id":"virtual-assistant-core-u4-l2-m1","name":"Typing Practice Guide.pdf","type":"pdf","url":""}],"content":"Practice touch typing, accuracy drills, and efficient data entry. Complete the timed typing assessment.","quizId":"virtual-assistant-core-u4-l2-quiz"}]}]}],"quizzes":[{"id":"virtual-assistant-basic-l1-quiz","programId":"virtual-assistant","title":"Reading, Writing & Comprehension Quiz","passing":75,"timeLimit":30,"published":true,"questions"